// InstrumentDesc: Complete instrument description (instrument.hpp). (SPEC-API)
void read(const Reader& r, InstrumentDesc& o) {
    ObjectScope s(r);
    if (!s.ok()) {
        return;
    }
    s.text("name", o.name, true, TextRule::Any);
    s.objects("groups", o.groups, true, 0);
    s.objects("bridgePoints", o.bridgePoints, true, 0);
    s.object("body", o.body, true);
    s.objects("channels", o.channels, true, 0);
    s.object("tuning", o.tuning, true);
    s.object("defaults", o.defaults, false);
    s.finish();
}

void write(const InstrumentDesc& o, OJson& j) {
    j = OJson::object();
    j["name"] = o.name;
    j["groups"] = OJson::array();
    for (const auto& e : o.groups) { write(e, j["groups"].emplace_back()); }
    j["bridgePoints"] = OJson::array();
    for (const auto& e : o.bridgePoints) { write(e, j["bridgePoints"].emplace_back()); }
    write(o.body, j["body"]);
    j["channels"] = OJson::array();
    for (const auto& e : o.channels) { write(e, j["channels"].emplace_back()); }
    write(o.tuning, j["tuning"]);
    write(o.defaults, j["defaults"]);
}

